import boto3, os, time

client = boto3.client('emr-serverless')
app_id  = os.environ['EMR_APP_ID']
bucket  = os.environ['S3_BUCKET']

response = client.start_job_run(
    applicationId=app_id,
    executionRoleArn=os.environ['EMR_JOB_ROLE_ARN'],
    jobDriver={
        'sparkSubmit': {
            'entryPoint': f's3://{bucket}/scripts/etl.py',
            'entryPointArguments': [
                '--input',  f's3://{bucket}/raw/tenant-a/',
                '--output', f's3://{bucket}/processed/tenant-a/',
                '--tenant', 'tenant-a',
            ],
            'sparkSubmitParameters': '--conf spark.executor.cores=4 --conf spark.executor.memory=8g --conf spark.dynamicAllocation.enabled=true',
        }
    },
    configurationOverrides={
        'monitoringConfiguration': {
            's3MonitoringConfiguration': {'logUri': f's3://{bucket}/logs/emr-serverless/'}
        }
    }
)

job_run_id = response['jobRunId']
print(f'Submitted job run: {job_run_id}')

while True:
    run = client.get_job_run(applicationId=app_id, jobRunId=job_run_id)['jobRun']
    status = run['state']
    print(f'Status: {status}')
    if status == 'SUCCESS':
        break
    if status in ('FAILED', 'CANCELLED', 'CANCELLING'):
        raise RuntimeError(f'EMR Serverless job failed: {status} — {run.get("stateDetails", "")}')
    time.sleep(30)

import boto3, os, time

client = boto3.client('emr-serverless')
app_id  = os.environ['EMR_APP_ID']
bucket  = os.environ['S3_BUCKET']

response = client.start_job_run(
    applicationId=app_id,
    executionRoleArn=os.environ['EMR_JOB_ROLE_ARN'],
    jobDriver={
        'sparkSubmit': {
            'entryPoint': f's3://{bucket}/scripts/quality_check.py',
            'entryPointArguments': [
                '--input',  f's3://{bucket}/processed/tenant-a/',
                '--tenant', 'tenant-a',
                '--report', f's3://{bucket}/dq-reports/tenant-a/',
            ],
            'sparkSubmitParameters': f'--jars s3://{bucket}/scripts/deequ-2.0.7-spark-3.5.jar --py-files s3://{bucket}/scripts/pydeequ.zip --conf spark.emr-serverless.driverEnv.SPARK_VERSION=3.5 --conf spark.executorEnv.SPARK_VERSION=3.5',
        }
    },
    configurationOverrides={
        'monitoringConfiguration': {
            's3MonitoringConfiguration': {'logUri': f's3://{bucket}/logs/deequ/'}
        }
    }
)

job_run_id = response['jobRunId']
print(f'Quality check job run: {job_run_id}')

while True:
    run = client.get_job_run(applicationId=app_id, jobRunId=job_run_id)['jobRun']
    status = run['state']
    print(f'Status: {status}')
    if status == 'SUCCESS':
        print('Data quality passed')
        break
    if status in ('FAILED', 'CANCELLED', 'CANCELLING'):
        raise RuntimeError(f'DATA QUALITY FAILED — Redshift load blocked. State: {status}')
    time.sleep(20)
